import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import cn from 'classnames'
import * as React from 'react'
import {createSelector} from 'reselect'

import styles from './VirtualizedTreeExpandHandle.module.css'

type Props = {
  expanded?: boolean
  expandable: boolean
  indent: number
  className: string
  onClick?: () => unknown
  tabIndex?: number
  level?: number
}
const computeStyle = createSelector(
  (indent: number) => indent,
  indent => ({
    marginLeft: `${indent}px`,
  }),
)
function VirtualizedTreeExpandHandle({
  expanded,
  expandable,
  indent,
  className,
  onClick,
  tabIndex,
  level,
}: Props) {
  const style = computeStyle(indent)
  let chevronIcon
  if (level === 0) {
    chevronIcon = expanded ? 'caret-down-12px' : 'caret-right-12px'
  } else {
    chevronIcon = expanded ? 'chevron-down' : 'chevron-right'
  }
  return expandable && onClick != null ? (
    <IconButton
      title={expanded === true ? 'Collapse' : 'Expand'}
      style={style}
      className={cn(styles.chevronButton, className)}
      iconClassName={cn(styles.chevronIcon, {
        [styles.topLevel]: level === 0,
      })}
      icon={chevronIcon}
      onClick={onClick}
      tabIndex={tabIndex}
      data-test={expanded === true ? 'collapse-button' : 'expand-button'}
    />
  ) : (
    <span className={className} style={style} />
  )
}
export default React.memo(VirtualizedTreeExpandHandle)
