import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import cn from 'classnames'
import {memo, useContext} from 'react'

import MatchingTitle from '../../../../../../../common/MatchingItem/MatchingItem'
import SidebarLink from '../../../../../../../common/Sidebar/SidebarLink/SidebarLink'
import {QueueSidebarSearchContext} from '../../../QueueSidebar.contexts'
import styles from '../QueueSidebarPoolItem/QueueSidebarPoolItem.module.css'

type Props = {
  title: string
  to: string
  total: number | null | undefined
}

function QueueSidebarLinkItem({title, to, total}: Props) {
  const searchQuery = useContext(QueueSidebarSearchContext).searchQuery
  return (
    <SidebarLink
      to={to}
      className={cn(styles.link)}
      tail={<Tooltip title={'Builds in queue'}>{total}</Tooltip>}
      needsOffsetForChevron
    >
      <MatchingTitle searchQuery={searchQuery}>{title}</MatchingTitle>
    </SidebarLink>
  )
}

export default memo(QueueSidebarLinkItem)
