import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {memo, useContext} from 'react'
import type * as React from 'react'

import type {AgentPoolId} from '../../../../../../../../types'
import MatchingTitle from '../../../../../../../common/MatchingItem/MatchingItem'
import SidebarLink from '../../../../../../../common/Sidebar/SidebarLink/SidebarLink'
import {getQueuePoolHref} from '../../../../../../../pages/QueuePage/QueuePage.routes'
import {QueueSidebarSearchContext} from '../../../QueueSidebar.contexts'

import styles from './QueueSidebarPoolItem.module.css'

type Props = {
  title: string
  agentPoolId: AgentPoolId
  total: number | null | undefined
  ellipsisRef?: React.Ref<HTMLDivElement>
  needsOffsetForChevron?: boolean
}

function QueueSidebarPoolItem({
  title,
  agentPoolId,
  total,
  ellipsisRef,
  needsOffsetForChevron = true,
}: Props) {
  const searchQuery = useContext(QueueSidebarSearchContext).searchQuery
  return (
    <SidebarLink
      to={getQueuePoolHref(agentPoolId)}
      className={styles.link}
      tail={total ? <Tooltip title={'Builds in queue'}>{total}</Tooltip> : null}
      ellipsisRef={ellipsisRef}
      needsOffsetForChevron={needsOffsetForChevron}
    >
      <MatchingTitle searchQuery={searchQuery}>{title}</MatchingTitle>
    </SidebarLink>
  )
}

export default memo(QueueSidebarPoolItem)
