import classNames from 'classnames'
import type * as React from 'react'

import ExpandHandle from '../VirtualizedTreeExpandHandle/VirtualizedTreeExpandHandle'

import styles from './VirtualizedTreeItem.module.css'

type Props = {
  style: React.CSSProperties
  className: string
  // for consistency with VirtualizedTreeOverlayItem
  wrapperClassName?: string
  containerClassName?: string
  contentClassName?: string
  expandable?: boolean
  expanded?: boolean
  focusable?: boolean
  indent: number
  children: React.ReactNode
  onToggleExpand?: () => unknown
  level?: number
  wrapperHtmlProps?: React.JSX.IntrinsicElements['div']
}

function VirtualizedTreeItem({
  style,
  className,
  containerClassName,
  wrapperClassName,
  contentClassName,
  children,
  expandable = false,
  expanded = false,
  indent,
  onToggleExpand,
  wrapperHtmlProps,
  level,
}: Props) {
  return (
    <div role="row" style={style} className={containerClassName}>
      <div role="cell" className={styles.cell}>
        <div {...wrapperHtmlProps} className={classNames(styles.item, className, wrapperClassName)}>
          <ExpandHandle
            className={styles.expandHandle}
            expandable={expandable}
            expanded={expanded}
            indent={indent}
            onClick={onToggleExpand}
            tabIndex={-1}
            level={level}
          />
          <div className={classNames(styles.content, contentClassName)}>{children}</div>
        </div>
      </div>
    </div>
  )
}

export default VirtualizedTreeItem
