import Theme, {ThemeProvider} from '@jetbrains/ring-ui-built/components/global/theme'
import type {PopupAttrs} from '@jetbrains/ring-ui-built/components/popup/popup'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import cn from 'classnames'
import * as React from 'react'
import {useState} from 'react'

import useEventCallback from '../../../../hooks/useEventCallback'
import {getSandbox} from '../../../../utils/fastdom'
import Popup from '../../Popup/Popup.lazy'
import type {VirtualizedTreeNodeProps} from '../VirtualizedTree'
import {useShowPopup} from '../VirtualizedTree.contexts'
import ExpandHandle from '../VirtualizedTreeExpandHandle/VirtualizedTreeExpandHandle'

import styles from './VirtualizedTreeOverlayItem.module.css'

const TOOLTIP_OFFSET_LEFT = 20
const TOOLTIP_OFFSET_BOTTOM = 4
const OFFSET_LEFT_AND_RIGHT = 24
const popupDirections = [Directions.TOP_RIGHT]

const REGULAR_ITEM_HEIGHT = 24
const SIDEBAR_FOOTER_HEIGHT = 41
type Props = VirtualizedTreeNodeProps & {
  expandable?: boolean
  expanded?: boolean
  active?: boolean
  children: React.ReactNode
  className?: string
  wrapperClassName?: string
  hoveredClassName?: string
  focusedClassName?: string
  activeClassName?: string
  wrapperHtmlProps?: React.JSX.IntrinsicElements['div']
  popupHtmlProps?: Partial<PopupAttrs>
  popupContent?: React.ReactNode
  onToggleExpand?: () => unknown
  itemType?: string
  itemKey: string
}
type InnerProps = Props & {
  showPopup: boolean
  setShowPopup: (arg0: boolean) => unknown
}

const needsPopup = (width: number, indent: number, ellipsisRef?: React.RefObject<HTMLElement>) => {
  if (!ellipsisRef?.current || !width) {
    return false
  }
  return ellipsisRef.current.scrollWidth + indent + OFFSET_LEFT_AND_RIGHT > width
}

const VirtualizedTreeOverlayItemInner = React.memo(function VirtualizedTreeOverlayItemInner(
  props: InnerProps,
) {
  const {
    wrapperHtmlProps,
    width,
    ellipsisRef,
    style,
    className,
    focusedClassName = '',
    activeClassName = '',
    wrapperClassName,
    expandable = false,
    expanded = false,
    active = false,
    indent,
    onToggleExpand,
    children,
    popupContent,
    itemType,
    showPopup,
    setShowPopup,
    popupHtmlProps,
  } = props
  const [focused, setFocused] = useState(false)

  const openPopup = useEventCallback(() => {
    setShowPopup(true)
  })
  const closePopup = useEventCallback(() => {
    setShowPopup(false)
  })
  const onMouseEnter = useEventCallback(async (event: React.MouseEvent<any>) => {
    const {clientY, target} = event

    if (clientY > window.innerHeight - SIDEBAR_FOOTER_HEIGHT - REGULAR_ITEM_HEIGHT) {
      if (target != null && target instanceof Element) {
        const sandbox = getSandbox(target)
        const fullyFit = await sandbox.measure(
          () => target.getBoundingClientRect().bottom <= window.innerHeight - SIDEBAR_FOOTER_HEIGHT,
        )

        if (fullyFit) {
          sandbox.mutate(() => openPopup())
        }
      }
    } else {
      openPopup()
    }
  })

  const onFocus = useEventCallback(() => setFocused(true))
  const onBlur = useEventCallback((e: React.FocusEvent<HTMLDivElement>) => {
    setFocused(false)

    if (wrapperHtmlProps?.onBlur != null) {
      wrapperHtmlProps.onBlur(e)
    }
  })

  const childClassName = cn(
    styles.item,
    className,
    {
      [activeClassName]: active,
    },
    {
      [focusedClassName]: focused,
    },
  )
  const popupClassName = cn(styles.item, className, styles.tooltip)

  return (
    <div
      {...wrapperHtmlProps}
      style={style}
      className={wrapperClassName}
      role="row"
      onFocus={onFocus}
      onBlur={onBlur}
    >
      {showPopup && needsPopup(width, indent, ellipsisRef) && (
        <ThemeProvider theme={Theme.DARK} passToPopups>
          <Popup
            className={popupClassName}
            left={indent + TOOLTIP_OFFSET_LEFT}
            directions={popupDirections}
            offset={TOOLTIP_OFFSET_BOTTOM}
            {...popupHtmlProps}
          >
            <div className={styles.contentWrapper} tabIndex={-1}>
              <div className={cn(styles.contentWrapper, styles.popup)} tabIndex={-1}>
                {popupContent}
              </div>
            </div>
          </Popup>
        </ThemeProvider>
      )}
      <div
        role="cell"
        onMouseEnter={onMouseEnter}
        onMouseLeave={closePopup}
        className={childClassName}
        data-test={itemType}
      >
        <ExpandHandle
          className={styles.expandHandle}
          expandable={expandable}
          expanded={expanded}
          indent={indent}
          onClick={onToggleExpand}
          tabIndex={-1}
        />
        <div className={styles.contentWrapper}>{children}</div>
      </div>
    </div>
  )
})

export default function VirtualizedTreeOverlayItem(props: Props) {
  const [showPopup, setShowPopup] = useShowPopup(props.itemKey)
  return (
    <VirtualizedTreeOverlayItemInner {...props} showPopup={showPopup} setShowPopup={setShowPopup} />
  )
}
