import cn from 'classnames'
import {memo, useRef} from 'react'

import {stringifyId} from '../../../../../../../../types'
import styles from '../../../../../../../common/Sidebar/SidebarItem/SidebarItem.module.css'
import type {VirtualizedTreeChildProps} from '../../../../../../../common/VirtualizedTree/VirtualizedTree'
import VirtualizedTreeItem from '../../../../../../../common/VirtualizedTree/VirtualizedTreeItem/VirtualizedTreeItem'
import VirtualizedTreeOverlayItem from '../../../../../../../common/VirtualizedTree/VirtualizedTreeOverlayItem/VirtualizedTreeOverlayItem'
import type {QueueSidebarItemType} from '../../../QueueSidebar.types'
import QueueSidebarLinkItem from '../QueueSidebarLinkItem/QueueSidebarLinkItem'
import QueueSidebarPoolItem from '../QueueSidebarPoolItem/QueueSidebarPoolItem'

type Props = VirtualizedTreeChildProps<QueueSidebarItemType>

function QueueSidebarItem(props: Props) {
  const ellipsisRef = useRef<HTMLDivElement>(null)

  switch (props.item.type) {
    case 'queue-sidebar-pool': {
      const {item, ...restProps} = props
      const {id, title, type, active, counters} = item
      return (
        <VirtualizedTreeOverlayItem
          className={cn(styles.item, styles.hoverableItem)}
          activeClassName={cn(styles.activeItem)}
          hoveredClassName={styles.hoveredItem}
          wrapperClassName={cn(styles.itemWrapper, styles.selectHoverFocus)}
          active={active}
          expandable={false}
          itemType={type}
          itemKey={`${type}-${stringifyId(id)}`}
          ellipsisRef={ellipsisRef}
          popupContent={
            <QueueSidebarPoolItem
              title={title}
              agentPoolId={id}
              total={counters?.total || null}
              needsOffsetForChevron={false}
            />
          }
          {...restProps}
        >
          <QueueSidebarPoolItem
            title={title}
            agentPoolId={id}
            total={counters?.total || null}
            ellipsisRef={ellipsisRef}
          />
        </VirtualizedTreeOverlayItem>
      )
    }

    case 'queue-sidebar-link': {
      const {to, title, active, counters} = props.item
      return (
        <VirtualizedTreeItem
          {...props}
          className={cn(styles.item, styles.hoverableItem, styles.selectHoverFocus, {
            [styles.activeItem]: active,
          })}
          expandable={false}
        >
          <QueueSidebarLinkItem to={to} title={title} total={counters?.total || null} />
        </VirtualizedTreeItem>
      )
    }
    case 'queue-sidebar-pool-title': {
      const {title} = props.item
      return (
        <VirtualizedTreeItem {...props} className={cn(styles.item)} expandable={false}>
          <span className={styles.title}>{title}</span>
        </VirtualizedTreeItem>
      )
    }

    default:
      return null
  }
}

export default memo(QueueSidebarItem)
